solution.python:
class ListNode:
    def __init__(self, x):
        self.val = x
        self.next = None

def getIntersectionNode(headA, headB):
    if not headA or not headB:
        return None
    pa, pb = headA, headB
    while pa is not pb:
        pa = pa.next if pa else headB
        pb = pb.next if pb else headA
    return pa

solution.python_alt:
def getIntersectionNode(headA, headB):
    seen = set()
    cur = headA
    while cur:
        seen.add(cur)
        cur = cur.next
    cur = headB
    while cur:
        if cur in seen:
            return cur
        cur = cur.next
    return None
